field.css:
.cx-field *{box-sizing: border-box;}
.cx-field figure{margin: 0px;}
@keyframes ping { 
  0% { box-shadow: color-mix(in srgb, currentcolor 45%, transparent 55%) 0px 0px 0px 0px; }
  70%, 100% { box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 7px; }
}
.cx-field .field{border: 1px dashed var(--border); background: radial-gradient(circle at 1px 1px, var(--border) 1px, transparent 0) 0 0 / 16px 16px, var(--background); border-radius: 6px; margin: 22px 12px 0px; padding: 18px;}
.cx-field .field-blocks{grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: 20px; display: grid;}
.cx-field .field-block{text-align: center; min-width: 0px;}
.cx-field .field-ring{aspect-ratio: 1 / 1; width: 100%; max-width: 180px; margin: 0px auto; position: relative;}
.cx-field .field-ring svg{width: 100%; height: 100%; display: block; overflow: visible;}
.cx-field .ring-track{fill: none; stroke: var(--border); stroke-width: 1px; stroke-dasharray: 2, 4;}
.cx-field .g{fill: currentcolor; transform-box: fill-box; transform-origin: 50% center; animation: 0.45s ease-out 0s 1 normal both running dot-in;}
@keyframes dot-in { 
  0% { opacity: 0; transform: scale(0.2); }
}
.cx-field .g-l{color: var(--subtle); fill-opacity: 0.3;}
.cx-field .g-w{color: var(--foreground);}
.cx-field .fb-test .g-w{color: var(--primary);}
.cx-field .ring-center{pointer-events: none; flex-direction: column; justify-content: center; align-items: center; gap: 4px; display: flex; position: absolute; inset: 0px;}
.cx-field .ring-num{font: 600 clamp(1.6rem, 3.4vw, 2.4rem) / 1 var(--font-sans); letter-spacing: -0.02em; color: var(--foreground);}
.cx-field .ring-of{font: 500 11px / 1 var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted-foreground);}
.cx-field .fb-test .ring-num{color: var(--primary);}
.cx-field .field-label{border-top: 1px dashed var(--border); gap: 3px; margin-top: 12px; padding-top: 8px; display: grid;}
.cx-field .field-name{font: 500 11px / 1.3 var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase;}
.cx-field .fb-test .field-name{color: var(--primary);}
.cx-field .field-note{color: var(--muted-foreground); font-size: 12px; line-height: 1.4;}
.cx-field .field-cap{margin-top: 14px;}
.cx-field .field-legend{font: 500 11px / 1 var(--font-mono); letter-spacing: 0.05em; text-transform: uppercase; color: var(--foreground); align-items: center; gap: 6px; margin-right: 12px; display: inline-flex;}
.cx-field .field-key{background: var(--foreground); border-radius: 50%; width: 8px; height: 8px; display: inline-block;}
.cx-field .fk-l{background: var(--subtle); opacity: 0.3; margin-left: 6px;}
.cx-field .caption{color: var(--muted-foreground); font-size: 12.5px; line-height: 1.55;}
.cx-field .fig-no{font: 500 11px / 1 var(--font-mono); letter-spacing: 0.05em; text-transform: uppercase; color: var(--foreground); margin-right: 4px;}
.cx-field .caption{text-wrap: pretty;}
.cx-field figcaption{text-wrap: pretty;}

steps.css:
.cx-steps *{box-sizing: border-box;}
.cx-steps p,.cx-steps ol{margin: 0px;}
.cx-steps ol{padding: 0px; list-style: none;}
.cx-steps a{color: inherit;}
.cx-steps .stk{user-select: none; -webkit-user-drag: none; max-width: none; height: auto; filter: var(--shadow-sticker); display: block;}
@keyframes ping { 
  0% { box-shadow: color-mix(in srgb, currentcolor 45%, transparent 55%) 0px 0px 0px 0px; }
  70%, 100% { box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 7px; }
}
.cx-steps .steps{gap: 18px; display: grid;}
.cx-steps .step-tag{align-items: center; gap: 10px; padding: 0px 12px 6px; display: flex;}
.cx-steps .stk-tag{transition: transform 0.2s cubic-bezier(0.2, 0.7, 0.2, 1); transform: rotate(-6deg);}
.cx-steps .chip-serif{font: italic 400 18px / 1.25 var(--font-serif); background: var(--band); box-shadow: inset 0 0 0 1px var(--border); border-radius: 3px; padding: 2px 9px 1px; display: inline-block;}
.cx-steps .row{border-radius: 4px; align-items: center; gap: 12px; min-height: 44px; padding: 8px 12px; text-decoration: none; transition: background-color 0.15s; display: flex;}
.cx-steps .row-tall{align-items: flex-start;}
.cx-steps .row-text{flex: 1 1 0%; min-width: 0px;}
.cx-steps .row-title{text-wrap: balance; font: 500 15px / 1.45 var(--font-sans); transition: color 0.15s; display: block;}
.cx-steps .row-body{color: var(--muted-foreground); margin-top: 4px; font-size: 14px; line-height: 1.65; display: block;}
.cx-steps .row-body strong{color: var(--foreground); font-weight: 600;}
.cx-steps .row-arrow{fill: none; stroke: currentcolor; stroke-width: 1.4px; stroke-linecap: round; stroke-linejoin: round; width: 14px; height: 14px; color: color-mix(in srgb, var(--muted-foreground) 55%, transparent); flex: 0 0 auto; margin-top: 4px; transition: transform 0.2s, color 0.2s;}
@keyframes dot-in { 
  0% { opacity: 0; transform: scale(0.2); }
}
.cx-steps .row-body{max-width: 72ch;}
.cx-steps .row-body{text-wrap: pretty;}
.cx-steps p,.cx-steps li{text-wrap: pretty;}
.cx-steps code{font-family: var(--font-mono); color: var(--foreground); background: var(--band); box-shadow: inset 0 0 0 1px var(--border); border-radius: 5px; padding: 0.12em 0.36em; font-size: 0.86em;}

sessions.css:
.cx-sessions *{box-sizing: border-box;}
.cx-sessions p,.cx-sessions figure{margin: 0px;}
.cx-sessions .num{font-variant-numeric: tabular-nums lining-nums;}
@keyframes pulse { 
  50% { box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 7px; }
}
@keyframes resolve { 
  0% { opacity: 0; transform: translateY(-4px); }
  60% { opacity: 1; color: var(--foreground); }
}
.cx-sessions .fig-title{font: 500 .74rem / 1.3 var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted-foreground); margin-bottom: 1rem;}
.cx-sessions .caption{color: var(--muted-foreground); max-width: 54rem; margin-top: 1rem; font-size: 0.86rem; line-height: 1.55;}
.cx-sessions .fig-no{font: 500 .72rem / 1 var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--foreground); margin-right: 0.4rem;}
@keyframes march { 
  100% { stroke-dashoffset: -18px; }
}
.cx-sessions .arm-test{fill: var(--primary);}
.cx-sessions .arm-placebo{fill: var(--warning);}
.cx-sessions .arm-none{fill: var(--subtle);}
.cx-sessions .sessions-head{flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 1rem; display: flex;}
.cx-sessions .legend{color: var(--muted-foreground); align-items: center; gap: 0.4rem; font-size: 0.8rem; display: flex;}
.cx-sessions .arms{margin-top: 0.4rem;}
.cx-sessions .arm{border-bottom: 1px dashed var(--border); padding: 1rem 0px 1.05rem;}
.cx-sessions .arm-top{justify-content: space-between; align-items: flex-start; gap: 1rem; display: flex;}
.cx-sessions .arm-name{font-size: 0.95rem; font-weight: 600;}
.cx-sessions .arm-note{color: var(--muted-foreground); font-size: 0.78rem;}
.cx-sessions .arm-share{flex-direction: column; align-items: flex-end; line-height: 1.1; display: flex;}
.cx-sessions .arm-share > span:first-child{font: 450 1.55rem / 1.05 var(--font-serif);}
.cx-sessions .arm-test .arm-share > span:first-child{color: var(--primary);}
.cx-sessions .arm-count{color: var(--muted-foreground); font-size: 0.78rem;}
.cx-sessions .arm-models{gap: 5px; margin-top: 0.7rem; display: grid;}
.cx-sessions .arm-model{grid-template-columns: 7.4rem minmax(0px, 1fr); align-items: center; display: grid;}
.cx-sessions .arm-model-name{color: var(--muted-foreground); white-space: nowrap; font-size: 0.74rem;}
.cx-sessions .sq-run{flex-wrap: wrap; gap: 3px; display: flex;}
.cx-sessions .sq{width: 11px; height: 11px; box-shadow: inset 0 0 0 1px var(--border); background: var(--card); border-radius: 2px; display: inline-block;}
.cx-sessions .sq-on{background: var(--primary); box-shadow: none;}
.cx-sessions .legend .sq:last-of-type{margin-left: 0.7rem;}
.cx-sessions .caption{font-size: 15px; line-height: 1.7;}
.cx-sessions .sessions .sq-run{grid-template-columns: repeat(19, minmax(0px, 1fr)); gap: 4px; width: 100%; display: grid;}
.cx-sessions .sessions .sq-run .sq{aspect-ratio: 1 / 1; border-radius: 3px; width: auto; height: auto;}
.cx-sessions .sessions .arm-model{grid-template-columns: 9rem minmax(0px, 1fr); padding: 3px 0px;}
.cx-sessions .sessions .arm-model-name{font-size: 0.82rem;}
.cx-sessions p,.cx-sessions figcaption{text-wrap: pretty;}

apitrail.css:
.cx-apitrail *{box-sizing: border-box;}
.cx-apitrail code{font: .86em var(--font-mono); background: var(--muted); border: 1px dashed var(--border); overflow-wrap: anywhere; border-radius: 4px; padding: 0.05em 0.35em;}
@keyframes pulse { 
  50% { box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 7px; }
}
@keyframes resolve { 
  0% { opacity: 0; transform: translateY(-4px); }
  60% { opacity: 1; color: var(--foreground); }
}
@keyframes march { 
  100% { stroke-dashoffset: -18px; }
}
.cx-apitrail .ledger{border-collapse: collapse; width: 100%;}
.cx-apitrail .ledger th,.cx-apitrail .ledger td{border-bottom: 1px dashed var(--border); text-align: left; padding: 0.8rem 0px; font-weight: 400;}
.cx-apitrail .ledger td{text-align: right;}
.cx-apitrail .ledger th,.cx-apitrail .ledger td{border-bottom-style: dashed; border-bottom-color: var(--border);}
.cx-apitrail .ledger tbody th{color: var(--foreground); padding-right: 1.5rem; font-size: 0.96rem;}
.cx-apitrail .ledger td{font: 400 1rem var(--font-mono); white-space: nowrap;}
.cx-apitrail .sandbox-runs{width: 100%;}
.cx-apitrail .sandbox-runs thead th{text-align: left;}
.cx-apitrail .sandbox-runs tbody th,.cx-apitrail .sandbox-runs tbody td{vertical-align: top; white-space: normal; padding-right: 1rem;}
.cx-apitrail .sandbox-runs code{overflow-wrap: anywhere; font-size: 0.82rem;}
.cx-apitrail .sandbox-runs td{text-align: left;}
.cx-apitrail code{font-family: var(--font-mono); color: var(--foreground); background: var(--band); box-shadow: inset 0 0 0 1px var(--border); border-radius: 5px; padding: 0.12em 0.36em; font-size: 0.86em;}
